INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('456908d25cdcac539942e4ffcbe8f651', 'NEET', '11', 'Biology', 'bio_11_neet_aerobic_atp', 'Cellular Respiration', 'Aerobic ATP yield', '[]', '["glycolysis","Krebs cycle","oxidative phosphorylation","ATP yield","NADH/FADH₂"]', 0, 0, '[]', 'MCQ', NULL, 0, 2000, 'NEET_MEDIUM', 3, -1.0, 'During aerobic respiration, the complete oxidation of one molecule of glucose yields how many molecules of ATP (including substrate‑level phosphorylation and oxidative phosphorylation)?', '["2 ATP", "4 ATP", "30–32 ATP", "36–38 ATP"]', '36–38 ATP', 'Aerobic respiration consists of glycolysis (2 ATP), pyruvate oxidation (2 NADH → ~5 ATP), Krebs cycle (2 ATP + 6 NADH + 2 FADH₂ → ~15 ATP), and oxidative phosphorylation (≈ 26–28 ATP). Total is roughly 36–38 ATP per glucose molecule.', '["Step 1: Count ATP from glycolysis (2 ATP).", "Step 2: Add ATP equivalents from NADH and FADH₂ produced in pyruvate oxidation and Krebs cycle.", "Step 3: Sum all contributions to obtain the final range."]', '', 'biology.respiration.atp_yield', 'NEET Class 11', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:23', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-22T13:54:04.602Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('45696e2452a0a029302f57a9cef18676', 'Board', '10', 'Science', 'sci_10_control_reproductive_hormones', 'Control and Coordination', 'Reproductive Hormones', '[]', '["estrogen","secondary sexual characteristics","puberty","female hormones"]', 0, 0, '[]', 'MCQ', NULL, 0, 1180, 'BOARD_EASY', 3, 0.0, 'Which hormone is primarily responsible for the development of secondary sexual characteristics in females during puberty?', '["Estrogen", "Progesterone", "Follicle‑stimulating hormone (FSH)", "Luteinising hormone (LH)"]', 'Estrogen', 'Estrogen drives the growth of breasts, widening of hips, and other secondary sexual traits in females. Progesterone prepares the uterus for pregnancy, while FSH and LH regulate ovarian function but do not directly cause secondary characteristics.', '["Step 1: Identify the hormone that directly influences secondary sexual traits.", "Step 2: Recall that estrogen is the principal female sex hormone for these changes.", "Step 3: Select the option that names estrogen."]', '', 'science.reproductive_hormones.estrogen_vs_progesterone', 'Board Class 10', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:21', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-20T13:02:47.832Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('456d5bbf78dcf4d380cceba8d991eee8', 'NEET', '12', 'Biology', 'bio_12_neet_origin_of_life', 'Evolution', 'Origin of Life', '[]', '["Miller‑Urey","prebiotic synthesis","amino acids","primitive atmosphere","lightning simulation"]', 0, 0, '[]', 'MCQ', NULL, 0, 2000, 'NEET_MEDIUM', 4, -1.0, 'The Miller‑Urey experiment (1953) demonstrated that organic molecules could be synthesized under conditions thought to resemble the early Earth. Which of the following statements about the experimental setup is FALSE?', '["The apparatus contained a mixture of water, methane, ammonia, and hydrogen, which were thought to be the major constituents of the primitive atmosphere.", "Electrical discharges were used to simulate lightning, providing energy for the synthesis of organic compounds.", "The experiment produced only simple sugars such as glucose, but no amino acids.", "The resulting mixture contained amino acids like glycine and alanine, supporting the hypothesis that life''s building blocks could form abiotically."]', 'The experiment produced only simple sugars such as glucose, but no amino acids.', 'Miller and Urey observed the formation of several amino acids (e.g., glycine, alanine) after circulating a spark through a reducing gas mixture. No sugars were reported, making option C the false statement.', '["Step 1: Recall the gases used in the Miller‑Urey apparatus (CH₄, NH₃, H₂, H₂O).", "Step 2: Recognize that electrical discharges simulated lightning as the energy source.", "Step 3: Identify the actual products—primarily amino acids, not sugars.", "Step 4: Choose the statement that incorrectly describes the products."]', '', 'biology.evolution.miller_urey_false_statement', 'NEET Class 12', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:21', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-20T12:56:48.545Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('456d7f1c41f5ed843c80d651abc3386f', 'JEEMains', '11', 'Chemistry', 'chem_11_jm_structure_of_atom', 'Structure of Atom', 'Photoelectric effect and atomic spectra', '[]', '["photoelectric effect","photon energy","kinetic energy of photoelectrons","intensity vs frequency","Einstein''s equation"]', 0, 0, '[]', 'MCQ', NULL, 0, 2120, 'JEE_MAINS_MEDIUM', 4, -1.0, 'The photoelectric effect demonstrates the particle nature of light. If the wavelength of incident radiation is decreased while keeping intensity constant, what happens to the maximum kinetic energy and the photoelectric current?', '["Maximum KE increases, current remains same", "Maximum KE decreases, current increases", "Maximum KE increases, current increases", "Maximum KE remains same, current decreases"]', 'Maximum KE increases, current remains same', 'Decreasing wavelength increases frequency ($\nu = c/\lambda$). From Einstein''s equation: $K_{\text{max}} = h\nu - \phi$, so higher $\nu$ means higher $K_{\text{max}}$. Photoelectric current depends on number of photons (intensity), not frequency. Since intensity is constant, current remains unchanged.', '["Step 1: Relate wavelength to frequency: $\\nu = c/\\lambda$", "Step 2: Use $K_{\\text{max}} = h\\nu - \\phi$: as $\\nu$ increases, $K_{\\text{max}}$ increases", "Step 3: Current depends on photon count, which depends on intensity", "Step 4: Intensity constant ⇒ same number of photons ⇒ same current"]', 'K_{\text{max}} = h\nu - \phi', 'chemistry.atom.photoelectric_current_frequency_misconception', 'JEEMains Class 11', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:18', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-20T12:10:12.480Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('456e495985446d883bd2738492b55e1e', 'NEET', '11', 'Biology', 'bio_11_neet_nervous_system', 'Neural Control and Coordination', 'CNS brain parts and functions', '[]', '["hypothalamus","homeostasis","CNS","brain functions"]', 0, 0, '["Board"]', 'MCQ', NULL, 0, 1750, 'NEET_EASY', 2, -1.0, 'Which part of the human brain is primarily responsible for regulating body temperature, hunger, and thirst?', '["Cerebrum", "Hypothalamus", "Medulla oblongata", "Cerebellum"]', 'Hypothalamus', '[Duplicate Quarantined] Hypothalamus controls homeostatic functions like temperature, hunger, and thirst.', '["Identify homeostatic regulation center", "Recall hypothalamus governs autonomic functions"]', '', 'biology.neural_control.function_misattribution', 'NEET Class 11', NULL, 'D', 0.87, 'Recall', '2026-05-23 03:15:25', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-22T15:11:29.680Z', -1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('45710d2d757409ad6a112b6437187f8a', 'NEET', '11', 'Biology', 'bio_11_neet_photosynthesis', 'Photosynthesis in Higher Plants', 'Factors affecting photosynthesis light CO2 temp', '[]', '["limiting factor","light saturation","CO₂","photosynthesis"]', 0, 0, '["Board"]', 'MCQ', NULL, 0, 2000, 'NEET_MEDIUM', 3, -1.0, 'Which factor is the most limiting in the region of light saturation during photosynthesis?', '["Light", "CO₂", "Temperature", "Water"]', 'CO₂', 'At light saturation, CO₂ becomes the limiting factor.', '["Step 1: Light saturation reached", "Step 2: Further light increase has no effect", "Step 3: CO₂ now limits rate"]', '', 'bio.photosynthesis.limiting_factor_misconception', 'NEET Class 11', NULL, 'D', 0.87, 'Recall', '2026-05-23 03:15:25', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-22T15:13:54.456Z', -1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('45777f47f40edbf4b5f70b6d95c04e55', 'JEEMains', '12', 'Chemistry', 'chem_12_jm_solutions', 'Solutions', 'Molarity molality mole fraction normality', '[]', '["molarity","molality","density","solution concentration","mole fraction","normality","unit conversion","aqueous solution"]', 0, 0, '[]', 'MCQ', NULL, 0, 2400, 'JEE_MAINS_HARD', 3, -1.0, 'Which of the following expressions correctly relates molarity (M), molality (m), and density (d) of a solution?', '["$M = m \\times d$", "$M = \\frac{m \\times d}{1 + m M_w}$", "$m = \\frac{M}{d - M M_w}$", "$M = \\frac{1000 \\times m \\times d}{1000 + m M_w}$"]', '$m = \frac{M}{d - M M_w}$', 'Molality $m = \frac{\text{moles solute}}{\text{kg solvent}}$, derived using density and molarity.', '["Start from definitions of M and m", "Derive relation using mass and volume"]', 'm = \frac{M}{d - M M_w}', 'chemistry.solutions.density_relation_mistake', 'JEEMains Class 12', NULL, 'D', 0.87, 'Recall', '2026-05-23 03:15:25', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-22T15:13:15.271Z', -1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('4579190efc8f1161c89a8f8f8d3e38fa', 'JEEMains', '11', 'Physics', 'phy_11_jm_kinematics_2d', 'Motion in a Plane', 'Relative Velocity', '[]', '["relative velocity","vector addition","river flow","boat speed","2‑D kinematics"]', 0, 0, '[]', 'MCQ', NULL, 0, 2100, 'JEE_MAINS_MEDIUM', 4, -1.0, 'A boat can move with a speed of $5\ \text{m s}^{-1}$ relative to the water and is steered due north. The river flows due east at $3\ \text{m s}^{-1}$. Find the speed of the boat relative to the ground.', '["5.8 m/s", "8 m/s", "2 m/s", "5 m/s"]', '5.8 m/s', 'The ground velocity is the vector sum of the boat''s velocity relative to water (north) and the river''s velocity (east). Magnitude $=\sqrt{5^2+3^2}=\sqrt{34}\approx5.8\,\text{m s}^{-1}$.', '["Step 1: Represent the boat''s velocity relative to water as a vector $\\vec{v}_b = (0,5)\\ \\text{m s}^{-1}$ (east, north).", "Step 2: Represent the river''s velocity as $\\vec{v}_r = (3,0)\\ \\text{m s}^{-1}$.", "Step 3: Add the vectors: $\\vec{v}_{ground}=\\vec{v}_b+\\vec{v}_r = (3,5)\\ \\text{m s}^{-1}$.", "Step 4: Compute the magnitude $|\\vec{v}_{ground}| = \\sqrt{3^2+5^2}=\\sqrt{34}\\approx5.8\\ \\text{m s}^{-1}$."]', '$v_{ground}=\sqrt{v_{river}^2+v_{boat}^2}$', 'physics.kinematics.relative_velocity', 'JEEMains Class 11', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:20', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-20T12:49:01.783Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('457d643c19b45c6c11381b13bc354407', 'JEEMains', '11', 'Mathematics', 'math_11_jm_trigonometry', 'Trigonometric Functions', 'Properties of Triangles', '[]', '["sine rule","triangle properties","trigonometry ratios"]', 0, 0, '[]', 'MCQ', NULL, 0, 2100, 'JEE_MAINS_MEDIUM', 2, -1.0, 'In $\triangle ABC$, if $a=2$, $b=3$, and $\\\sin A = 1/3$, find $\\sin B$.', '["0.5", "0.6", "0.75", "0.25"]', '0.5', 'Apply sine rule $a/\\sin A = b/\\sin B$ and solve.', '["Use $a/\\\\sin A = b/\\\\sin B$.", "Substitute values: $2/(1/3) = 3/\\\\sin B$."]', 'a/\\sin A = b/\\sin B', 'math.trig.sine_rule_ratio', 'JEEMains Class 11', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:24', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-22T14:45:53.898Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('457d9961d3f624d90e26f498b98690bb', 'Board', '10', 'Science', 'phy_10_board_magnetism_straight_wire', 'Magnetic Effects of Current', 'Magnetic field due to a straight wire', '[]', '["Biot–Savart law","magnetic field","straight conductor","μ0","distance dependence"]', 0, 0, '[]', 'MCQ', NULL, 0, 1150, 'BOARD_EASY', 3, 0.0, 'A long straight wire carries a current of \(3\,\text{A}\). What is the magnitude of the magnetic field at a point \(5\,\text{cm}\) from the wire?', '["12 \\times 10^{-6}\\,\\text{T}", "6 \\times 10^{-6}\\,\\text{T}", "3 \\times 10^{-6}\\,\\text{T}", "24 \\times 10^{-6}\\,\\text{T}"]', '12 \times 10^{-6}\,\text{T}', 'Using \(B = \frac{\mu_0 I}{2\pi r}\) with \(\mu_0 = 4\pi\times10^{-7}\,\text{H·m}^{-1}\), \(I = 3\,\text{A}\) and \(r = 0.05\,\text{m}\), we get \(B = \frac{2\times10^{-7}\times3}{0.05}=1.2\times10^{-5}\,\text{T}=12\times10^{-6}\,\text{T}\).', '["Step 1: Write the formula for the magnetic field of a straight wire: \\(B = \\frac{\\mu_0 I}{2\\pi r}\\).", "Step 2: Substitute \\(\\mu_0 = 4\\pi\\times10^{-7}\\,\\text{H·m}^{-1}\\), \\(I = 3\\,\\text{A}\\) and \\(r = 0.05\\,\\text{m}\\).", "Step 3: Simplify to obtain \\(B = 12\\times10^{-6}\\,\\text{T}\\)."]', 'B = \frac{\mu_0 I}{2\pi r}', 'physics.board.magnetism.straight_wire', 'Board Class 10', NULL, 'D', 0.87, 'Recall', '2026-05-23 03:19:18', 'v2.1', 'Taxonomy alignment: updated class (10->10), exam (Board->Board), subject (Physics->Science) to match canonical taxonomy item sci_10_board_magnetism', '2026-05-22T13:42:21.315Z', -1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('45817c17d2f9dbe645477dcc5b3df120', 'JEEMains', '11', 'Chemistry', 'chem_11_jee_chemical_bonding', 'Chemical Bonding', 'Chemical Bonding and Molecular Structure', '[]', '["VSEPR Theory","Molecular Shape","Electrons"]', 0, 0, '[]', 'MCQ', NULL, 0, 2000, 'JEE_MAINS_EASY', 1, -1.0, '$\text{The VSEPR theory is used to predict the shape of molecules based on the arrangement of their }$', '["$\\text{electrons}$", "$\\text{protons}$", "$\\text{neutrons}$", "$\\text{atoms}$"]', '$\text{electrons}$', 'Step 1: Identify the application of VSEPR theory.', '[]', '', 'chem.chemical_bonding.vsepr_theory', 'JEEMains Class 11', NULL, 'D', 0.87, 'Recall', '2026-05-23 03:15:22', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-22T13:44:50.830Z', -1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('4582233a3497cde3b0fdd62eebc4693e', 'JEEMains', '11', 'Mathematics', 'math_11_jm_permutations_combinations', 'Permutations and Combinations', 'Fundamental principle multiplication addition', '[]', '["multiplication principle","counting","independent events"]', 0, 0, '["Board"]', 'MCQ', NULL, 0, 1900, 'JEE_MAINS_EASY', 2, -1.0, 'A man has 5 shirts and 4 pants. In how many ways can he dress if each shirt can be paired with any pant?', '["9", "10", "15", "20"]', '20', 'By multiplication principle: $5 \times 4 = 20$ ways.', '["Choose shirt: 5 ways", "Choose pant: 4 ways", "Total = 5×4 = 20"]', 'm \times n', 'math.pnc.multiplication_addition_confusion', 'JEEMains Class 11', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:25', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-22T15:02:30.572Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('4588ddc79ad40eff2cbc13d7cd8fcf6d', 'NEET', '12', 'Biology', 'bio_12_neet_ecosystem', 'Ecosystem and Environment', 'Community interactions mutualism predation parasitism', '[]', '["Mutualism","Symbiotic Relationship","Community Interactions"]', 0, 0, '["NEET"]', 'MCQ', NULL, 0, 1800, 'NEET_EASY', 2, -1.0, 'A community of organisms is said to be in a state of mutualism when all the organisms in the community benefit from each other''s presence. What is an example of mutualism in nature?', '["Predation", "Parasitism", "Symbiotic relationship between a coral and a fish", "Symbiotic relationship between a fungus and a tree"]', 'Symbiotic relationship between a coral and a fish', 'Step 1: Recall the definition of mutualism: a community of organisms where all members benefit from each other''s presence,Step 2: Identify an example of mutualism: the symbiotic relationship between a coral and a fish', '["Step 1: Recall the definition of mutualism: a community of organisms where all members benefit from each other''s presence", "Step 2: Identify an example of mutualism: the symbiotic relationship between a coral and a fish"]', '', 'biology.ecosystem.community_interactions', 'JEEMains Class 12', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:24', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-22T14:09:40.770Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('458925dfc351b72081424ab1ea620563', 'Board', '8', 'Science', 'sci_08_light', 'Light', 'Luminous and non‑luminous objects', '[]', '["luminous objects","non‑luminous objects","reflection of light","light sources","visibility"]', 0, 0, '[]', 'MCQ', NULL, 0, 820, 'CLASS_8_RECALL', 3, 0.0, 'Which of the following is a non‑luminous object?', '["The Sun", "A fluorescent lamp", "The Moon", "A candle"]', 'The Moon', 'A non‑luminous object does not emit its own light; it only reflects light from other sources. The Moon reflects sunlight, whereas the Sun, a lamp, and a candle emit light themselves.', '["Step 1: Identify the definition of a non‑luminous object.", "Step 2: Examine each option to see whether it emits light or merely reflects it.", "Step 3: Choose the object that only reflects light."]', '', 'science.light.luminous_nonluminous.definition', 'Board Class 8', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:20', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-20T12:50:33.766Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('4589f6b6d3d07158087027549b80172d', 'NEET', '12', 'Biology', 'bio_12_neet_ecosystem', 'Ecosystem and Environment', 'Biogeochemical cycles carbon nitrogen phosphorus', '[]', '["Biogeochemical cycles","Ecosystem and environment","Carbon cycle","Nitrogen cycle","Phosphorus cycle"]', 0, 0, '[]', 'MCQ', NULL, 0, 1750, 'NEET_EASY', 3, -1.0, '$\text{The ecosystem and environment are closely linked through biogeochemical cycles. Which of the following biogeochemical cycles involves the movement of carbon, nitrogen, and phosphorus?}$', '["Carbon cycle", "Nitrogen cycle", "Phosphorus cycle", "All of the above"]', 'All of the above', 'Step 1: Identify the biogeochemical cycles involved in the movement of carbon, nitrogen, and phosphorus.
Step 2: Recognize that all three cycles are interconnected and involve the movement of these elements.
Step 3: Conclude that the correct answer is the one that includes all three cycles.', '["Step 1: Identify the biogeochemical cycles involved in the movement of carbon, nitrogen, and phosphorus.", "Step 2: Recognize that all three cycles are interconnected and involve the movement of these elements.", "Step 3: Conclude that the correct answer is the one that includes all three cycles."]', '', 'general.exam_trap', 'NEET Class 12', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:18', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-20T12:21:14.475Z', 1);
