INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('458a6297891893b77dde63ec34bfc1a9', 'JEEMains', '11', 'Mathematics', 'math_11_jm_circle_general_form', 'Conic Sections', 'Circle – standard and general forms', '[]', '["standard form of a circle","centre and radius","coordinate geometry","algebraic manipulation"]', 0, 0, '[]', 'MCQ', NULL, 0, 1900, 'JEE_MAINS_EASY', 4, -1.0, 'Find the equation of the circle whose centre is \((2,\,-3)\) and whose radius is \(5\) units.', '["(x-2)² + (y+3)² = 25", "(x+2)² + (y-3)² = 25", "(x-2)² + (y-3)² = 25", "(x+2)² + (y+3)² = 25"]', '(x-2)² + (y+3)² = 25', 'The standard form of a circle is \((x-h)² + (y-k)² = r²\). Substituting \(h=2\), \(k=-3\) (so \(y-(-3)=y+3\)), and \(r=5\) gives \((x-2)² + (y+3)² = 25\).', '["Step 1: Recall the standard circle equation \\((x-h)² + (y-k)² = r²\\).", "Step 2: Insert the centre coordinates \\(h=2\\) and \\(k=-3\\).", "Step 3: Square the radius \\(5\\) to obtain \\(r² = 25\\).", "Step 4: Write the final equation."]', '(x-h)² + (y-k)² = r²', 'math.geometry.circle_general_form', 'JEEMains Class 11', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:24', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-22T14:14:26.742Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('45965a462396183e663b14462b1fa5c4', 'JEEMains', '12', 'Chemistry', 'chem_12_jm_chemical_kinetics', 'Chemical Kinetics', 'Molecularity vs order of reaction', '[]', '["order of reaction","molecularity","rate law","elementary reaction","fractional order"]', 0, 0, '[]', 'MCQ', NULL, 0, 1950, 'JEE_MAINS_EASY', 4, -1.0, 'For a reaction, the rate law is found to be $\text{Rate} = k[A]^{3/2}[B]^0$. Which of the following statements is correct regarding the order and molecularity of the reaction?', '["Order = 1.5, Molecularity = 1.5", "Order = 1.5, Molecularity = 2", "Order = 0, Molecularity = 1", "Order = 1.5, Molecularity cannot be 1.5"]', 'Order = 1.5, Molecularity cannot be 1.5', 'Order is the sum of exponents in rate law: $\frac{3}{2} + 0 = 1.5$. Molecularity is the number of reacting species in an elementary reaction and must be a whole number (1, 2, or 3). It cannot be fractional. So while order can be 1.5, molecularity cannot be 1.5. The reaction is likely complex (non-elementary).', '["Step 1: Determine order: exponent of [A] is 1.5, [B] is 0 → total order = 1.5", "Step 2: Recall molecularity applies only to elementary reactions", "Step 3: Molecularity must be integer: 1, 2, or 3", "Step 4: Hence, molecularity cannot be 1.5"]', '\text{Order} = \sum \text{exponents in rate law}', 'chemistry.kinetics.molecularity_fractional_misconception', 'JEEMains Class 12', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:17', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-20T11:58:09.344Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('459ae3c6638211f3d7d0b12c4e22ff3a', 'JEEMains', '11', 'Physics', 'phy_11_jm_gyroscope', 'Rotational Motion', 'Gyroscopic Precession', '[]', '["gyroscope","precession","torque","angular momentum","rotational dynamics"]', 0, 0, '[]', 'MCQ', NULL, 0, 2150, 'JEE_MAINS_MEDIUM', 3, -1.0, 'A gyroscope consisting of a spinning wheel of moment of inertia $I$ and angular speed $\omega$ is mounted on a horizontal axle. When a torque $\tau$ is applied about the vertical axis, the gyroscope precesses with angular velocity $\Omega$. Which of the following relations correctly gives $\Omega$?', '["$\\displaystyle \\Omega = \\frac{\\tau}{I\\,\\omega}$", "$\\displaystyle \\Omega = \\frac{I\\,\\omega}{\\tau}$", "$\\displaystyle \\Omega = \\frac{\\tau}{I}$", "$\\displaystyle \\Omega = I\\,\\omega\\,\\tau$"]', '$\displaystyle \Omega = \frac{\tau}{I\,\omega}$', 'The gyroscopic precession relation is $\tau = I\,\omega\,\Omega$, therefore $\Omega = \tau/(I\,\omega)$. Option A matches this expression.', '["Step 1: Recall the gyroscopic precession formula $\\tau = I\\,\\omega\\,\\Omega$.", "Step 2: Rearrange to solve for $\\Omega$: $\\Omega = \\tau/(I\\,\\omega)$.", "Step 3: Identify the option that matches the derived expression."]', '$\tau = I\,\omega\,\Omega$', 'physics.rotational.gyroscope_precession', 'JEEMains Class 11', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:19', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-20T12:32:45.258Z', 1);
