INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('45a805b715e4c88dd2b021fffd6ebbb1', 'JEEMains', '11', 'Mathematics', 'math_11_jm_limits_derivatives', 'Limits and Derivatives', 'Derivative as slope of tangent', '[]', '["derivative","tangent slope","polynomial differentiation","power rule","calculus"]', 0, 0, '[]', 'Integer', NULL, 0, 1850, 'JEE_MAINS_EASY', 2, 0.0, 'Find the slope of the tangent to the curve $y = x^3 - 3x + 2$ at the point where $x = 2$.', '[]', '9', 'Differentiate: $\frac{dy}{dx}=3x^2-3$. Substituting $x=2$ gives $3(2)^2-3=12-3=9$. Hence the slope is 9.', '["Step 1: Differentiate the function using the power rule.", "Step 2: Substitute $x=2$ into the derivative.", "Step 3: Simplify to obtain the slope."]', '$\frac{dy}{dx}=3x^2-3$', 'mathematics.calculus.derivative_power_rule', 'JEEMains Class 11', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:19', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-20T12:33:29.475Z', 1);
